import{z as s,x as d,o as i,c as A,q as n,j as t,D as r,d as E,s as B,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const U=JSON.parse('{"title":"未定义行为","description":"","frontmatter":{"title":"未定义行为","date":"2026-09-10T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/undefined-behavior.md","filePath":"cs/undefined-behavior.md","lastUpdated":1791063341000}'),p={name:"cs/undefined-behavior.md"};function c(C,a,m,h,u,f){const o=d("Mermaid");return i(),A("div",null,[a[2]||(a[2]=n('<h1 id="未定义行为" tabindex="-1">未定义行为 <a class="header-anchor" href="#未定义行为" aria-label="Permalink to &quot;未定义行为&quot;">​</a></h1><div class="epigraph"><p>标准不规定后果的运算，编译器可以假定它从不发生；于是带未定义行为的程序在优化之后可以变成另一份程序。</p><footer>—— 据 ISO/IEC 9899:2018；Kernighan &amp; Ritchie, The C Programming Language, 2nd ed. 整理</footer></div><p>上一课<a href="/cs/recursion-stack-frame">递归与栈帧</a>把「一调用一帧、返回即失效」钉死。本课不重讲深度，也不从形式语义教科书另起。缺口是：栈溢出、越界下标、空指针解引用，在语言里是什么地位？<strong>哪些写法根本没有语义，因而「在我机器上能跑」不能当规格</strong>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ISO C 的抽象机器给合法程序逐步语义。一旦执行到未定义行为（UB），标准不再约束任何后果：崩溃、看似成功、删掉整段代码、跨翻译单元传播，都允许。缺口因此不是 bug 清单，而是<strong>语言契约的方向</strong>：程序员保证 UB 不发生，编译器才有权按「这事不会发生」做优化。违反之后，调试版本与发行版本分叉是常态，不是工具链坏了。</p><p>前面几课已经埋了火种：返回后的栈地址、未对齐强转、越出数组对象的指针。本课给它们一个总名，并分清旁边两个更容易混的词：未指定与实现定义。后两课再把整数溢出与悬挂指针从总名里拆开细讲。</p><p><span class="marginnote">「抽象机器」是标准里那台想象中的 C 机器：合法程序在它上面有逐步语义。UB 就是抽象机器直接宕机——此后标准对你程序的一切表现都不再背书。</span></p><h3 id="ub-不是「可能得错误结果」" tabindex="-1">UB 不是「可能得错误结果」 <a class="header-anchor" href="#ub-不是「可能得错误结果」" aria-label="Permalink to &quot;UB 不是「可能得错误结果」&quot;">​</a></h3><p>未指定（unspecified）：必须在若干合法结果里选一个，例如参数求值顺序。实现定义（implementation-defined）：必须合法且写进文档，例如 <code>char</code> 是否有符号。UB 没有这种仁慈——有符号溢出后 <code>i+1 &lt; i</code> 可以为真，编译器可以删掉你以为在「防溢出」的分支。把三类都叫做「平台相关」，后课的 sanitizer 与代码审查会对不准靶。</p><p><span class="marginnote">ISO C 附录 J 汇总未定义行为。K&amp;R 年代许多习惯写法今天仍是 UB。地址与未定义行为 sanitizer 是工程上的探测器，它们不改语言规则，只让违规更早可见。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>判断顺序：先问是否离开对象寿命或对象边界，再问类型是否允许这样别名，再问算术是否在类型范围内。常见源：空指针或悬空指针解引用、越界、有符号溢出、违反有效类型的别名、数据竞争（C11 起对数据竞争也是 UB）。本课只建立分类；整数与寿命各用后面一课钉死。</p>',12)),(i(),t(l,null,{default:r(()=>[B(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20LEGAL%5B%22%E5%90%88%E6%B3%95%EF%BC%9A%E6%8A%BD%E8%B1%A1%E6%9C%BA%E5%99%A8%E6%9C%89%E8%AF%AD%E4%B9%89%22%5D%0A%20%20LEGAL%20--%3E%20OPT%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E6%8C%89%E6%97%A0%20UB%20%E6%94%B9%E5%86%99%22%5D%0A%20%20BAD%5B%22%E8%A7%A6%E5%8F%91%E6%9C%AA%E5%AE%9A%E4%B9%89%E8%A1%8C%E4%B8%BA%22%5D%20--%3E%20ANY%5B%22%E5%90%8E%E6%9E%9C%E4%B8%8D%E5%8F%97%E6%A0%87%E5%87%86%E7%BA%A6%E6%9D%9F%22%5D%0A%20%20ANY%20-.-%3E%20OPT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"「我看了汇编，这条 load 还在」不能证明程序合法：换优化等级、换链接时优化、换内联决定，同一源可能被改写成另一条路径。合法程序的可观察行为才是规格；UB 程序没有可观察行为可谈。",-1)),a[4]||(a[4]=e("p",null,[E("实现定义与未指定仍要求程序继续有语义，只是你不能把某一次观察写成可移植规格。例如移位负值、"),e("code",null,"char"),E(" 的符号性。写可移植代码就把这些当成不可用，除非接口明确依赖某份 ABI。UB 更狠：连「继续跑」都不必。后课两例——有符号溢出与悬挂——覆盖了算术与对象两条最常见的河。其余（严格别名、并发数据竞争）在出现相应对象模型时再点名，不在本课造清单。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"同一份带 UB 的源码，在不同优化等级下如何走出两条路：",-1)),(i(),t(l,null,{default:r(()=>[B(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOOP%5B%22%E5%90%8C%E4%B8%80%E4%BB%BD%E5%90%AB%E8%B6%8A%E7%95%8C%E5%86%99%E6%B3%95%E7%9A%84%E6%BA%90%E7%A0%81%22%5D%20--%3E%20O0%5B%22-O0%EF%BC%9A%E6%8C%89%E6%BA%90%E7%A0%81%E9%80%90%E6%9D%A1%E7%BF%BB%E8%AF%91%22%5D%0A%20%20O0%20--%3E%20RUN1%5B%22%E5%AE%9E%E6%B5%8B%E3%80%8E%E8%83%BD%E7%94%A8%E3%80%8F%E2%80%94%E2%80%94%E5%81%87%E8%B1%A1%22%5D%0A%20%20LOOP%20--%3E%20O2%5B%22-O2%EF%BC%9A%E5%81%87%E8%AE%BE%E8%B6%8A%E7%95%8C%E4%B8%8D%E5%8F%91%E7%94%9F%22%5D%0A%20%20O2%20--%3E%20CUT%5B%22%E8%AE%A4%E5%AE%9A%E6%A3%80%E6%9F%A5%E6%81%92%E5%81%87%EF%BC%8C%E5%88%A0%E5%88%86%E6%94%AF%E6%88%96%E6%94%B9%E5%BE%AA%E7%8E%AF%22%5D%0A%20%20CUT%20--%3E%20RUN2%5B%22%E8%A1%8C%E4%B8%BA%E6%94%B9%E5%86%99%EF%BC%8C%E5%B4%A9%E6%BA%83%E7%82%B9%E8%BF%9C%E7%A6%BB%E8%82%87%E4%BA%8B%E8%A1%8C%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<p>优化器利用「无 UB」做常量传播、消除所谓不可能的分支、重排访存。链接时优化把假设跨过翻译单元。于是一段在 <code>-O0</code> 下「能用」的越界循环，在 <code>-O2</code> 下可能被认定上界永远成立而删掉检查。这不是编译器恶意，是契约被打破后的合法改写。</p><p><span class="marginnote">直觉类比：UB 像保险合同里的除外条款——编译器假设你永不越界，你一旦越界，保单作废，它之后做的任何改写都「合法」；崩溃点常常离肇事代码很远，这正是 UB 难查的原因。</span></p><p>安全编码规范（CERT C、MISRA）的核心策略就是禁止进入 UB 构造，用可移植的子集换回可预测性。那是工程边界，不是本课要另起的语言。</p><p>与错误码课将要出现的「合法失败」对照：返回 <code>-1</code> 仍在抽象机器里。UB 是连失败语义都没有。因此「检查 <code>i+1</code> 是否溢出」若写成有符号加法后再比较，检查本身可能已被优化掉。必须用更宽类型、无符号模运算或标准库的检查原语，在溢出发生前分支。sanitizer 在动态执行路径上插桩，覆盖不到的路径仍可藏 UB。后课整数与寿命只是把本课的总名拆成两条最常踩的河。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不罗列附录 J 的每一条，也不讲 C++ 的更长清单。下一课<a href="/cs/integer-overflow">整数溢出</a>专讲有符号与无符号的分岔。后课默认：UB 一旦发生即无保证；不能靠一次实测定义语义；sanitizer 辅助发现，不替代规范。</p><p>同一份源在不同优化等级下的分叉，应首先当 UB 线索，而不是去关优化。合法程序的可观察行为在抽象机器上不依赖「碰巧没删掉那次检查」。把 <code>-O0</code> 能跑当成规格，等于把实现残留写成标准。</p><p><span class="marginnote">常见误区：初学者以为「我看了汇编，那条 load 还在」就算数。换优化等级、换内联决定，同一份源码可能被改写成另一条路径——合法程序的可观察行为才是规格，UB 程序没有规格可谈。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>未定义行为让标准停止给出语义；优化器按「不会发生」改写程序。</li><li>它不同于未指定与实现定义；后两者仍在合法结果集合内。</li><li>越界、非法指针、有符号溢出是主干上最常见的源。</li><li>下一课把溢出从这条总规则里拆开。</li><li>出处：ISO/IEC 9899；K&amp;R 对不可移植写法的警告。</li></ul>',10))])}const b=s(p,[["render",c]]);export{U as __pageData,b as default};
